/**
 * appendToFlowVariables
 * ---------------------
 * Type-only helper that appends element(s) to **array-typed** Flow variables while keeping full compile-time safety.
 *
 *
 * Rules:
 * - `definition` may be either the flow-execution ID (`Now.ID.…`) or the same ID wrapped in an object that also
 * carries an `annotation` string.
 * - `variables` is the schema returned by {@link FlowVariables}.
 * - Keys in `values` must reference array-typed variables — non-array targets are rejected at compile time.
 * - Each value can be a single element, an array of elements, or a string template compatible with the element type.
 *
 * This helper is erased at runtime – it only influences the TypeScript type-checker. The build plugin reads the AST to
 * emit the corresponding `sys_hub_flow_logic_instance_v2` record.
 *
 * @param definition  Flow execution identifier (+ optional annotation).
 * @param variables   Schema produced by {@link FlowVariables}.
 * @param values      Partial map keyed by array-typed variable names with the element(s) to append.
 */
import type { FlowVariableDefinition } from '../FlowVariables'

// runtime placeholder for type-only helper in value space.
//
// `V` is inferred structurally from the `variables` argument (the already-resolved TS shape of
// `params.flowVariables`), so the "array-only targets" rule can be expressed cleanly via `V[K] extends Array<infer E>`
// without trying to reverse-infer the raw schema. Routing through `FlowSchemaType<S>` (the way SetFlowVariables does
// for its value argument) doesn't work here because the conditional needs each key's resolved shape, not the raw
// `FlowArrayType` wrapper.
//
// The value arm `E | E[] | unknown[] | string` covers the four shapes the platform accepts:
//   - `E`         — a single element appended to the array
//   - `E[]`       — a literal array of elements (each appended)
//   - `unknown[]` — a datapill that resolves to an array of any element shape (the platform matches
//                   by structure at runtime, not by field name; this also lets the real-instance
//                   XMLs round-trip when the source author wired array-shaped datapills whose
//                   element schemas don't line up by name)
//   - `string`    — a template string / pill expression for the whole field
export declare function AppendToFlowVariables<
    T extends FlowVariableDefinition,
    V extends Record<string, unknown>,
    KV extends {
        [K in keyof V]?: V[K] extends Array<infer E> ? E | E[] | unknown[] | string : never
    },
>(definition: T, variables: V, values: KV): { type: 'appendflowvariables' }
